import '@testing-library/jest-dom/vitest'

import { fireEvent, render, screen, waitFor } from '@testing-library/react'
import { MemoryRouter } from 'react-router-dom'
import { beforeEach, describe, expect, it, vi } from 'vitest'

const mocks = vi.hoisted(() => ({ get: vi.fn(), post: vi.fn() }))
vi.mock('../../services/apiClient', () => ({ apiClient: mocks }))

import { ApprovalsPage } from './ApprovalsPage'

const queuedCase = (id: string, priority = 'Routine') => ({
  id,
  episodeId: 'episode',
  memberId: 'member',
  status: 'PendingDoctorReview',
  priority,
  createdAt: '2026-09-30T08:00:00Z',
})

const review = (id: string) => ({ ...queuedCase(id), traces: [] })

describe('ApprovalsPage', () => {
  beforeEach(() => {
    mocks.get.mockReset()
    mocks.post.mockReset()
  })

  it('shows a retryable error when selected case evidence fails to load', async () => {
    mocks.get
      .mockResolvedValueOnce({ data: { items: [queuedCase('synthetic-case-01')] } })
      .mockRejectedValueOnce(new Error('synthetic fetch failure'))
      .mockResolvedValueOnce({ data: review('synthetic-case-01') })
      .mockResolvedValueOnce({ data: { clinicalAccess: true, vitals: [], labReports: [] } })

    render(
      <MemoryRouter>
        <ApprovalsPage />
      </MemoryRouter>,
    )

    expect(await screen.findByText('Case evidence could not be loaded.')).toBeInTheDocument()
    fireEvent.click(screen.getByRole('button', { name: /try again/i }))
    await waitFor(() =>
      expect(screen.getByRole('heading', { name: /review case synthetic-case-01/i })).toBeInTheDocument(),
    )
    expect(mocks.get).toHaveBeenCalledWith('/doctors/me/members/member')
  })

  it('keeps a stale review response from replacing the current selected case', async () => {
    let resolveFirstReview!: (value: { data: ReturnType<typeof review> }) => void
    const firstReview = new Promise<{ data: ReturnType<typeof review> }>((resolve) => {
      resolveFirstReview = resolve
    })
    mocks.get.mockImplementation((url: string) => {
      if (url === '/doctors/me/cases')
        return Promise.resolve({ data: { items: [queuedCase('case-a'), queuedCase('case-b', 'Priority')] } })
      if (url === '/triage-cases/case-a/review') return firstReview
      return Promise.resolve({ data: review('case-b') })
    })

    render(
      <MemoryRouter>
        <ApprovalsPage />
      </MemoryRouter>,
    )
    await screen.findByRole('button', { name: /review case case-b/i })
    fireEvent.click(screen.getByRole('button', { name: /review case case-b/i }))
    await screen.findByRole('heading', { name: /review case case-b/i })
    resolveFirstReview({ data: review('case-a') })

    await waitFor(() =>
      expect(screen.getByRole('heading', { name: /review case case-b/i })).toBeInTheDocument(),
    )
    expect(screen.queryByRole('heading', { name: /review case case-a/i })).not.toBeInTheDocument()
  })

  it('uses a queued case deep link only when the case is in the authorized review queue', async () => {
    mocks.get.mockImplementation((url: string) => {
      if (url === '/doctors/me/cases')
        return Promise.resolve({ data: { items: [queuedCase('case-a'), queuedCase('case-b')] } })
      return Promise.resolve({ data: review('case-b') })
    })

    render(
      <MemoryRouter initialEntries={['/approvals?case=case-b']}>
        <ApprovalsPage />
      </MemoryRouter>,
    )

    await screen.findByRole('heading', { name: /review case case-b/i })
    expect(screen.getByRole('button', { name: /review case case-b/i })).toHaveAttribute(
      'aria-pressed',
      'true',
    )
    expect(mocks.get).toHaveBeenCalledWith('/triage-cases/case-b/review')
  })

  it('keeps decisions disabled until the current review is ready and saves only after confirmation', async () => {
    let resolveReview!: (value: { data: ReturnType<typeof review> }) => void
    const pendingReview = new Promise<{ data: ReturnType<typeof review> }>((resolve) => {
      resolveReview = resolve
    })
    mocks.get.mockImplementation((url: string) =>
      url === '/doctors/me/cases'
        ? Promise.resolve({ data: { items: [queuedCase('case-a')] } })
        : pendingReview,
    )
    mocks.post.mockResolvedValue({ data: {} })

    render(
      <MemoryRouter>
        <ApprovalsPage />
      </MemoryRouter>,
    )
    const approve = await screen.findByRole('button', { name: 'Approve' })
    expect(approve).toBeDisabled()
    resolveReview({ data: review('case-a') })
    await waitFor(() => expect(approve).toBeEnabled())
    fireEvent.change(screen.getByLabelText('Final Patient Guidance'), {
      target: { value: 'Please arrange an in-person clinical review.' },
    })
    fireEvent.click(approve)

    const dialog = await screen.findByRole('dialog', { name: /approve · request case-a/i })
    expect(dialog).toHaveTextContent('Please arrange an in-person clinical review.')
    expect(mocks.post).not.toHaveBeenCalled()
    fireEvent.click(screen.getByRole('button', { name: 'Confirm decision' }))

    await waitFor(() =>
      expect(mocks.post).toHaveBeenCalledWith('/triage-cases/case-a/approve', expect.any(Object)),
    )
  })

  it('blocks approval without approved guidance and lets the doctor cancel a decision', async () => {
    mocks.get.mockImplementation((url: string) =>
      url === '/doctors/me/cases'
        ? Promise.resolve({ data: { items: [queuedCase('case-a')] } })
        : Promise.resolve({ data: review('case-a') }),
    )

    render(
      <MemoryRouter>
        <ApprovalsPage />
      </MemoryRouter>,
    )
    const approve = await screen.findByRole('button', { name: 'Approve' })
    await waitFor(() => expect(approve).toBeEnabled())
    fireEvent.click(approve)
    expect(screen.getByText(/choose one approved guidance option/i)).toBeInTheDocument()
    expect(screen.queryByRole('dialog')).not.toBeInTheDocument()

    fireEvent.click(screen.getByRole('button', { name: 'Reject' }))
    await screen.findByRole('dialog')
    fireEvent.click(screen.getByRole('button', { name: 'Cancel' }))
    expect(screen.queryByRole('dialog')).not.toBeInTheDocument()
    expect(mocks.post).not.toHaveBeenCalled()
  })

  it('keeps the confirm dialog open when Escape is pressed while the decision is saving', async () => {
    mocks.get.mockImplementation((url: string) =>
      url === '/doctors/me/cases'
        ? Promise.resolve({ data: { items: [queuedCase('case-a')] } })
        : Promise.resolve({ data: review('case-a') }),
    )
    let resolvePost!: (value: { data: object }) => void
    mocks.post.mockReturnValue(
      new Promise<{ data: object }>((resolve) => {
        resolvePost = resolve
      }),
    )

    render(
      <MemoryRouter>
        <ApprovalsPage />
      </MemoryRouter>,
    )
    const reject = await screen.findByRole('button', { name: 'Reject' })
    await waitFor(() => expect(reject).toBeEnabled())
    fireEvent.click(reject)
    fireEvent.click(await screen.findByRole('button', { name: 'Confirm decision' }))
    await waitFor(() => expect(mocks.post).toHaveBeenCalled())

    fireEvent.keyDown(document, { key: 'Escape' })
    expect(screen.getByRole('dialog')).toBeInTheDocument()

    resolvePost({ data: {} })
    await waitFor(() => expect(screen.queryByRole('dialog')).not.toBeInTheDocument())
  })

  it('filters the queue by priority and by search text', async () => {
    mocks.get.mockImplementation((url: string) => {
      if (url === '/doctors/me/cases')
        return Promise.resolve({ data: { items: [queuedCase('case-a'), queuedCase('case-b', 'Priority')] } })
      return Promise.resolve({ data: review('case-a') })
    })

    render(
      <MemoryRouter>
        <ApprovalsPage />
      </MemoryRouter>,
    )
    await screen.findByRole('button', { name: /review case case-b/i })
    fireEvent.click(screen.getByRole('button', { name: 'Priority (1)' }))
    expect(screen.queryByRole('button', { name: /review case case-a/i })).not.toBeInTheDocument()
    expect(screen.getByRole('button', { name: /review case case-b/i })).toBeInTheDocument()

    fireEvent.click(screen.getByRole('button', { name: 'All (2)' }))
    fireEvent.change(screen.getByLabelText('Search cases'), { target: { value: 'zzz' } })
    expect(screen.getByText(/no matching cases/i)).toBeInTheDocument()
  })
  it('shows submitted symptoms in Why this case needs review for a routine request', async () => {
    mocks.get.mockImplementation((url: string) => Promise.resolve({ data: url === '/doctors/me/cases'
      ? { items: [queuedCase('synthetic-review')] }
      : { ...review('synthetic-review'), submittedEpisode: {
          id: 'synthetic-episode', memberId: 'member', symptoms: ['Synthetic symptom'],
          durationDays: 2, severity: 4, createdAt: '2026-10-03T08:00:00Z',
        } } }))
    render(<MemoryRouter><ApprovalsPage /></MemoryRouter>)
    expect(await screen.findByText('Submitted symptoms: Synthetic symptom. Reported duration: 2 days. This submitted episode requires clinician review.')).toBeInTheDocument()
  })

})
